(() => {
const $=s=>document.querySelector(s);
const icons={Home:'<rect x="4" y="4" width="5" height="5" rx=".6"/><rect x="15" y="4" width="5" height="5" rx=".6"/><rect x="4" y="15" width="5" height="5" rx=".6"/><rect x="15" y="15" width="5" height="5" rx=".6"/>',Media:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',Phone:'<path d="M6 3h4l1 5-3 2a13 13 0 0 0 6 6l2-3 5 1v4c0 6-18-2-18-12Z"/>',Energy:'<path class="solid" d="m14 2-9 12h6l-1 8 9-13h-6Z"/>',Vehicle:'<path d="m5 9 2-4h10l2 4M3 10h18v8H3ZM6 18v3m12-3v3M6 13h2m8 0h2"/>',Settings:'<path d="m9 3 1-2h4l1 2 2 1 2-.2 2 3.4-1.2 1.7v2.2l1.2 1.7-2 3.4-2-.2-2 1-1 2h-4l-1-2-2-1-2 .2-2-3.4L4.2 11V8.9L3 7.2l2-3.4 2 .2Z" transform="translate(0 2)"/><circle cx="12" cy="12" r="3"/>',Mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',Previous:'<path d="M5 5v14m14-14L8 12l11 7Z"/>',Next:'<path d="M19 5v14M5 5l11 7-11 7Z"/>',Play:'<path class="solid" d="m8 4 12 8-12 8Z"/>',Pause:'<path d="M8 4v16M16 4v16" stroke-width="4"/>',List:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1m-1 6h1m-1 6h1"/>',Seat:'<path d="M8 3v8l5 3h6M6 11l-2 8h15M11 7l1-3m3 5 1-3m3 6 1-3"/>',Fan:'<circle cx="12" cy="12" r="2"/><path class="solid" d="M11 9C4 8 7 1 11 2c3 1 2 5 0 7Zm4 2c1-7 8-4 7 0-1 3-5 2-7 0Zm-2 4c7 1 4 8 0 7-3-1-2-5 0-7Zm-4-2c-1 7-8 4-7 0 1-3 5-2 7 0Z"/>',Defog:'<path d="M2 16 4 6q8-5 16 0l2 10ZM7 17V8m5 9V7m5 10V8M5 10l2-2 2 2m1-1 2-2 2 2m1 1 2-2 2 2"/>',Rear:'<rect x="3" y="5" width="18" height="13" rx="1"/><path d="M8 21V7m4 14V7m4 14V7"/>',Turn:'<path d="M5 21V9a4 4 0 0 1 4-4h12m-5-4 5 4-5 4"/>',Arrow:'<path d="m9 4 8 8-8 8"/>',Close:'<path d="m6 6 12 12M6 18 18 6"/>',Volume:'<path d="m4 10 5-4v12l-5-4H1v-4Zm9-3q6 5 0 10m3-14q10 9 0 18"/>'};
icons.Clock='<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>';icons.Flag='<path d="M5 22V3q4-3 8 0t7 0v10q-4 3-7 0t-8 0"/>';
icons.Spotify='<circle cx="12" cy="12" r="10" fill="#1ed760" stroke="none"/><path d="M6 9q6-2 12 1M7 12q5-1.5 10 1M8 15q4-1 8 .7" stroke="#0c1722" stroke-width="1.6"/>';icons.Lock='<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>';icons.Window='<path d="M3 18V6h18v12ZM3 13h18M7 6l5 7"/>';icons.Bluetooth='<path d="m8 6 9 11-5 4V3l5 4-9 11"/>';icons.Wifi='<path d="M2 8q10-8 20 0M5 12q7-6 14 0M8 16q4-4 8 0"/><circle cx="12" cy="20" r="1"/>';
icons.Door='<path d="M5 21V3h10l4 6v12ZM5 10h14M13 15h3"/>';icons.Tailgate='<path d="M4 20V9h16v11ZM4 9l3-6h10l3 6M9 16h6"/>';
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.Home}</svg>`;
const state={app:'Home',driving:false,speed:0,battery:82,range:426,temp:22,passenger:22,playing:true,track:0,voice:false,assistant:'Ready',reply:'Try “find a faster route”.',lane:true,cruise:true,traffic:true,fan:true,seat:false,defog:false,rear:false,route:'original',zoom:1,panX:0,panY:0,phone:true,locked:true,charge:false,door:false,tailgate:false,windows:false,bluetooth:true,wifi:true,ambient:true,settingsTab:'Vehicle',chargeLimit:90,journeyMs:0,journeyProgress:0};
const tracks=[['Drifters','Nova Line'],['Afterglow','Nova Line'],['Blue Horizon','MEAVEN Sessions']];
let player=null,recognition=null,thinkTimer=null,bootTimer=null,driveFrame=null,bootFrame=null,trafficStartedAt=null,audioContext=null,drag=null,renderedApp=null;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4000)}
function speak(key,lakeside=true){if(!state.voice)return;if(key==='welcome')key='welcome-v17';player?.pause();player=new Audio('../../assets/audio/altair/'+(lakeside?'lakeside/':'')+key+'.mp3');state.assistant='Speaking';syncAI();player.onended=()=>{state.assistant='Ready';syncAI()};player.onerror=()=>{state.assistant='Ready';syncAI();toast('Voice clip unavailable. You can continue with the on-screen controls.')};player.play().catch(()=>{state.assistant='Ready';syncAI();toast('Choose Hear Lauren to enable audio.')})}
function reply(t,key){state.reply=t;state.assistant='Ready';render();if(key)speak(key)}
function orb(){return `<div class="ai-orb" aria-hidden="true"><svg viewBox="0 0 140 140"><defs><radialGradient id="orb-fill" cx=".72" cy=".21" r=".86"><stop stop-color="#b8a8ff"/><stop offset=".28" stop-color="#7150ff"/><stop offset=".6" stop-color="#152c9a"/><stop offset=".83" stop-color="#087fe8"/><stop offset="1" stop-color="#26ddff"/></radialGradient><linearGradient id="orb-wave" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#fff" stop-opacity=".95"/><stop offset=".45" stop-color="#91dfff"/><stop offset="1" stop-color="#a688ff"/></linearGradient><clipPath id="orb-clip"><circle cx="70" cy="70" r="62"/></clipPath><radialGradient id="orb-light" cx="0" cy=".3" r="1"><stop stop-color="#e6ffff" stop-opacity=".85"/><stop offset=".45" stop-color="#7decff" stop-opacity=".08"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><circle cx="70" cy="70" r="62" fill="url(#orb-fill)"/><g clip-path="url(#orb-clip)"><ellipse class="orb-halo" cx="43" cy="53" rx="37" ry="65" fill="none" stroke="#befbff" stroke-opacity=".65" stroke-width="1" transform="rotate(-31 43 53)"/><path class="orb-ribbon" d="M-2 70C22 121 54 117 76 98S117 66 143 91C128 130 99 147 64 134" fill="none" stroke="url(#orb-wave)" stroke-width="2"/><path d="M-2 74C23 127 60 109 83 94S121 74 143 95L150 150H-5Z" fill="#5a48ff" fill-opacity=".2"/><circle cx="70" cy="70" r="62" fill="url(#orb-light)"/></g><circle cx="70" cy="70" r="62" fill="none" stroke="#a3edff" stroke-width="1.5"/><path d="M19 36Q62-9 113 26" stroke="#eeefff" stroke-opacity=".75" stroke-width="2" fill="none"/></svg></div>`}
function car(){return `<svg class="blue-car" viewBox="428 337 52 46" role="img" aria-label="Blue MEAVEN SUV rear view from supplied reference"><defs><clipPath id="reference-car-clip"><path d="M443 340Q454 337 466 340L471 349 478 357 478 373Q456 383 431 374L430 357 436 349Z"/></clipPath></defs><image href="../../assets/images/altair/lakeside-reference-v15.png" width="1916" height="821" clip-path="url(#reference-car-clip)"/></svg>`}

function trafficSequence(){if(!state.driving||trafficStartedAt===null||matchMedia('(prefers-reduced-motion:reduce)').matches)return '';const elapsed=(performance.now()-trafficStartedAt)/1000;const bus=`<svg class="traffic-model bus-model" viewBox="0 0 52 74" aria-hidden="true"><path d="M8 12 12 3h28l5 9 3 53H5Z" fill="#97b2c1" stroke="#c8e2ed" stroke-width="1.2"/><path d="M12 5h28l3 8H9Z" fill="#bfd4df"/><rect x="10" y="16" width="31" height="25" rx="3" fill="#17374c" stroke="#cedee5" stroke-width="1"/><path d="M25 17v23M11 46h29m-29 5h29m-28 5h27" stroke="#536f80" stroke-width="1.2"/><rect x="18" y="44" width="15" height="4" rx="1" fill="#bfdce4"/><path d="M9 60h7m20 0h7" stroke="#e2a0aa" stroke-width="3"/><rect x="5" y="64" width="6" height="8" rx="2" fill="#0b1c2a"/><rect x="41" y="64" width="6" height="8" rx="2" fill="#0b1c2a"/></svg>`;return [['left',0,6,'car'],['right',1.3,6.5,'car'],['right',7.5,7,'bus'],['left',14.5,6,'car'],['right',17,6.5,'car']].map(([side,delay,duration,type])=>elapsed>=delay+duration?'':`<div class="traffic-vehicle ${side} ${type}" aria-hidden="true" data-traffic-kind="${type}" style="--traffic-delay:${delay-elapsed}s;--traffic-duration:${duration}s">${type==='bus'?bus:car().replace('class="blue-car"','class="traffic-model"')}</div>`).join('')}
function journey(){const saved=Math.floor(state.journeyProgress/25);const base=state.route==='original'?24:22;return {distance:300-state.journeyProgress,eta:'18:'+String(base-saved).padStart(2,'0'),remaining:((state.route==='original'?6.2:5.8)-state.journeyProgress/1000).toFixed(1),minutes:(state.route==='original'?22:20)-saved}}
function syncJourney(){syncMapMarker(true);const j=journey();document.querySelectorAll('[data-journey-distance]').forEach(e=>e.textContent=j.distance);document.querySelectorAll('[data-journey-eta]').forEach(e=>e.textContent=j.eta);document.querySelectorAll('[data-journey-remaining]').forEach(e=>e.textContent=j.remaining);document.querySelectorAll('[data-journey-minutes]').forEach(e=>e.textContent=j.minutes)}
function driver(){return `<section class="driver-display" aria-label="Driver display"><div class="drive-label"><strong>${state.driving?'Drive':'Park'}</strong><span>${state.driving?'READY':'PARKED'}</span></div><div class="speed-contours" aria-hidden="true"><svg viewBox="0 0 300 180">${Array.from({length:9},(_,i)=>`<path class="contour-base" d="M295 ${173-i*3}H${109+i*5}Q${-17+i*4} ${166-i*2} ${5+i*5} 4"/>`).join('')}${Array.from({length:4},(_,i)=>`<path class="speed-stream" style="--stream-delay:${-i*.32}s" pathLength="100" d="M295 ${173-i*7}H${109+i*11}Q${-17+i*8} ${166-i*4} ${5+i*10} 4"/>`).join('')}</svg></div><div class="speed"><strong>${state.speed}</strong><span>km/h</span></div><div class="gear-selector" aria-label="Selected gear ${state.driving?'D':'P'}">${['P','N','R','D'].map(g=>`<span class="${g===(state.driving?'D':'P')?'selected':''}" ${g===(state.driving?'D':'P')?'aria-current="true"':''}>${g}</span>`).join('')}</div><button class="driver-arrival" data-action="route-detail" aria-label="Journey recap"><strong>${icon('Clock')}<span data-journey-eta>${journey().eta}</span></strong><span>${icon('Flag')}<span data-journey-remaining>${journey().remaining}</span> km left</span></button><button class="driver-turn" data-action="route-detail"><span class="turn-distance">${icon('Turn')}<strong><span data-journey-distance>${journey().distance}</span> <small>m</small></strong></span><span class="turn-street">Turn right · ${state.route==='original'?'Lakeside A5':'Riverside Dr.'}</span></button><div class="road-visual" data-moving="${state.driving}"><svg viewBox="0 0 250 140" aria-hidden="true"><defs><linearGradient id="lane-surface" x2="0" y2="1"><stop stop-color="#073a6a" stop-opacity=".1"/><stop offset="1" stop-color="#075b9a" stop-opacity=".48"/></linearGradient></defs><path d="M105 0 0 140h250L145 0Z" fill="url(#lane-surface)"/><path d="M105 0 0 140m112-140L70 140M133 0l47 140M145 0l105 140" fill="none" stroke="#00bcff" stroke-opacity=".8" stroke-width="1.2"/><path class="lane-dashes" d="M113 5 55 140m82-135 58 135" fill="none" stroke="#40caff" stroke-width="1" stroke-dasharray="7 17"/></svg>${trafficSequence()}${car()}<span class="vehicle-scan" aria-hidden="true"></span></div><div class="driver-energy"><div><span class="battery-icon"><i style="width:${state.battery}%"></i></span><strong>${state.battery}%</strong></div><i></i><strong>${state.range} km</strong><small>Range</small></div><section class="assistant-display" aria-label="Lauren voice control">${ai()}</section></section>`}
function music(){const t=tracks[state.track];return `<article class="music-strip" aria-label="Music player"><button class="track-art" data-app="Media" aria-label="Open media library"><svg viewBox="0 0 50 50" aria-hidden="true"><defs><linearGradient id="album-sky" x2="0" y2="1"><stop stop-color="#00b9ff"/><stop offset="1" stop-color="#0756e3"/></linearGradient></defs><rect width="50" height="50" rx="5" fill="url(#album-sky)"/><path d="m0 30 19-8 16 7 15-8v29H0" fill="#a0dfff"/><path d="m0 36 25-13 25 13v14H0" fill="#0562c0"/><path d="m0 36 27 8 23-8v14H0" fill="#002a8c"/></svg></button><button class="track-name" data-app="Media"><strong>${t[0]}</strong><small>${icon('Spotify')}${t[1]}</small></button><div class="playback"><button data-action="previous" aria-label="Previous track">${icon('Previous')}</button><button data-action="play" aria-label="${state.playing?'Pause':'Play'} media">${icon(state.playing?'Pause':'Play')}</button><button data-action="next" aria-label="Next track">${icon('Next')}</button><button data-app="Media" aria-label="Open playlist">${icon('List')}</button></div></article>`}
function ai(){return `<div class="assistant-home" data-state="${state.assistant.toLowerCase()}"><div class="compact-orb">${orb()}</div><div class="greeting"><span class="ai-tag"><i></i>Lauren · AI voice</span><p id="ai-caption" aria-live="polite">${state.reply}</p></div><div class="voice-controls"><span class="voice-wave ${['Speaking','Listening','Thinking'].includes(state.assistant)?'active':''}" aria-hidden="true">${'<i></i>'.repeat(7)}</span><button data-action="talk" aria-label="${state.assistant==='Listening'?'Stop listening':'Start assistant'}">${icon('Mic')}</button></div></div>`}
function card(label,value,detail,action,mark='Vehicle',pressed){return `<button class="control-card" data-action="${action}" ${pressed===undefined?'':`aria-pressed="${pressed}"`}><span class="card-top">${icon(mark)}<span>${label}</span><i class="${pressed?'on':''}"></i></span><strong>${value}</strong><small>${detail}</small></button>`}
function appPanel(){let content='',title='',sub='';const t=tracks[state.track];if(state.app==='Settings'){title='Settings';sub='Vehicle & connections';content=`<nav class="settings-tabs" aria-label="Settings categories">${['Vehicle','Connections','Comfort'].map(tab=>`<button data-settings-tab="${tab}" aria-pressed="${state.settingsTab===tab}">${tab}</button>`).join('')}</nav><div class="control-grid">${state.settingsTab==='Vehicle'?card('Central locking',state.locked?'Locked':'Unlocked','All doors · '+(state.driving?'Park to change':'Tap to '+(state.locked?'unlock':'lock')),'lock','Lock',state.locked)+card('Driver door',state.door?'Open':'Closed',state.locked?'Unlock before opening':'Tap to '+(state.door?'close':'open'),'door','Door',state.door)+card('Windows',state.windows?'Open':'Closed','All windows · tap to change','windows','Window',state.windows)+card('Tailgate',state.tailgate?'Open':'Closed',state.locked?'Unlock before opening':'Tap to '+(state.tailgate?'close':'open'),'tailgate','Tailgate',state.tailgate):state.settingsTab==='Connections'?card('Bluetooth',state.bluetooth?'On':'Off',state.bluetooth&&state.phone?'Alex’s phone connected':'Tap to change','bluetooth','Bluetooth',state.bluetooth)+card('Wi-Fi',state.wifi?'Connected':'Off','MEAVEN hotspot · demo','wifi','Wifi',state.wifi)+card('Phone',state.phone?'Paired':'Not paired','Demo device · '+(state.phone?'disconnect':'connect'),'phone','Phone',state.phone)+card('Mobile network','5G','Tap to view connection details','network','Wifi',true):card('Seat comfort',state.seat?'On':'Off','Driver seat · tap to change','seat','Seat',state.seat)+card('Ambient lighting',state.ambient?'Ocean blue':'Off','Cabin illumination','ambient','Energy',state.ambient)+card('Lauren’s voice',state.voice?'On':'Off','Optional neural voice responses','voice','Mic',state.voice)+card('Cabin fan',state.fan?'On':'Off',state.temp.toFixed(1)+'° driver · '+state.passenger.toFixed(1)+'° passenger','fan','Fan',state.fan)}</div>`}else if(state.app==='Energy'){title='Energy';sub=state.charge?'Charging · simulated session':'Battery & charging';const target=Math.max(0,state.chargeLimit-state.battery);content=`<div class="energy-layout"><div class="battery-feature"><div class="battery-ring" style="--charge:${state.battery}%"><strong>${state.battery}<small>%</small></strong></div><div><span>Usable battery</span><strong>${state.range} km</strong><small>Estimated range</small></div></div><div class="energy-detail"><div class="kpi-grid"><article><small>Charging power</small><strong>${state.charge?'150':'0'} <span>kW</span></strong></article><article><small>To ${state.chargeLimit}%</small><strong>${target===0?'Ready':Math.ceil(target*2.2)+' min'}</strong></article><article><small>Consumption</small><strong>18.4 <span>kWh/100 km</span></strong></article><article><small>Arrival charge</small><strong>${state.route==='original'?'42':'45'}<span>%</span></strong></article></div><div class="charge-controls"><div><span>Charge limit</span>${[80,90,100].map(n=>`<button data-charge-limit="${n}" aria-pressed="${state.chargeLimit===n}">${n}%</button>`).join('')}</div><button class="screen-primary" data-action="charge">${state.charge?'Stop demo charge':state.driving?'Park to charge':'Start demo charge'}</button></div><small class="session-note">${state.charge?'DC session · +5% added to demo battery':state.driving?'Park the vehicle to start a charging simulation.':'CCS ready · choose your charge limit.'}</small></div></div>`}else if(state.app==='Media'){title=`${icon('Spotify')} Spotify`;sub='Connected · demo library';content=`<div class="spotify-layout"><article class="now-playing-card"><div class="large-album" aria-hidden="true"><span>MEAVEN</span><i></i><small>LAKESIDE SESSIONS</small></div><div class="now-playing-copy"><small>NOW PLAYING</small><h3>${t[0]}</h3><p>${t[1]}</p><div class="media-progress"><i class="${state.playing?'playing':''}"></i></div><div class="media-timestamps"><span>1:24</span><span>4:12</span></div><div class="full-playback"><button data-action="previous" aria-label="Previous Spotify track">${icon('Previous')}</button><button data-action="play" class="spotify-play" aria-label="${state.playing?'Pause':'Play'} Spotify">${icon(state.playing?'Pause':'Play')}</button><button data-action="next" aria-label="Next Spotify track">${icon('Next')}</button><button data-action="like" aria-pressed="${!!state.liked}" aria-label="Save track">${state.liked?'♥':'♡'}</button></div></div></article><div class="spotify-queue"><span>Made for your drive</span>${tracks.map((track,i)=>`<button data-track="${i}" aria-pressed="${state.track===i}"><span class="queue-index">${i+1}</span><span><strong>${track[0]}</strong><small>${track[1]}</small></span>${state.track===i?'<i class="equalizer">▂▆▃</i>':icon('Play')}</button>`).join('')}</div></div>`}else{title='Phone';sub='Devices & calling';content=`<div class="phone-layout"><div class="phone-connection">${icon('Phone')}<strong>${state.phone&&state.bluetooth?'Alex’s phone':'No device connected'}</strong><span>${state.phone&&state.bluetooth?'Bluetooth · signal strong':'Connect a demo phone to explore'}</span><button class="screen-primary" data-action="phone">${state.phone?'Disconnect':'Connect'} demo phone</button></div><div class="phone-options">${card('Bluetooth',state.bluetooth?'On':'Off','Wireless connection','bluetooth','Bluetooth',state.bluetooth)}${card('Mobile network','5G','Connection details','network','Wifi',true)}<small>Demo connection. No calls are placed.</small></div></div>`}return `<section class="application-screen" aria-label="${state.app==='Media'?'Spotify':state.app} page"><header class="application-header"><div><h2>${title}</h2><span>${sub}</span></div><button data-app="Home" class="back-map">${icon('Arrow')} Map</button></header>${content}</section>`}

const mapView={minZoom:.65,maxZoom:1.7,panX:280,panY:180};const mapAnchors=new Map();
function mapTransform(){return `translate(${330+state.panX} ${120+state.panY}) scale(${state.zoom}) translate(-330 -120)`}
function applyMapView(){state.panX=Math.max(-mapView.panX,Math.min(mapView.panX,state.panX));state.panY=Math.max(-mapView.panY,Math.min(mapView.panY,state.panY));$('#map-art')?.setAttribute('transform',mapTransform());const out=$('[data-action="map-out"]'),inside=$('[data-action="map-in"]');if(out)out.disabled=state.zoom<=mapView.minZoom;if(inside)inside.disabled=state.zoom>=mapView.maxZoom}
function zoomMap(delta){state.zoom=Math.max(mapView.minZoom,Math.min(mapView.maxZoom,Math.round((state.zoom+delta)*100)/100));applyMapView()}
function syncMapMarker(animate=false){const route=$('#map-navigation-route'),marker=$('.map-position');if(!route||!marker)return;let anchor=mapAnchors.get(state.route);if(anchor===undefined){const total=route.getTotalLength();let best=Infinity;for(let i=0;i<=300;i++){const length=total*i/300,p=route.getPointAtLength(length),distance=(p.x-362)**2+(p.y-125)**2;if(distance<best){best=distance;anchor=length}}mapAnchors.set(state.route,anchor)}const p=route.getPointAtLength(Math.max(0,anchor-state.journeyProgress*.14));marker.style.transition=animate?'transform 4.8s linear':'none';marker.style.transform=`translate(${p.x}px,${p.y}px)`;marker.dataset.journeyProgress=state.journeyProgress}
function cityMap(){let streets='',blocks='';for(let i=-24;i<57;i++){const x=170+i*25;streets+=`<path d="M${x+165} -600Q${x+75} -280 ${x} -30Q${x-58} 95 ${x-113} 270T${x-340} 840"/>`;}for(let i=-40;i<63;i++){const y=i*15-40;streets+=`<path d="M-720 ${y+65}Q-210 ${y+30} 160 ${y}Q380 ${y-30} 760 ${y+25}T1440 ${y+70}"/>`;}for(let y=-594;y<840;y+=22)for(let x=-110;x<1440;x+=31){if((x+y)%9<3)continue;blocks+=`<path d="m${x} ${y} 20-2-7 12-20 2Z" fill="#48758a" fill-opacity=".18"/><path d="m${x} ${y}v-5l20-2v5Z" fill="#7291a0" fill-opacity=".12"/>`;}const coast='M188 -600C245 -490 140 -350 207 -210S250 -100 214 -30C191 0 161 22 172 50S226 72 216 105 176 133 187 164 239 202 224 270C178 355 265 405 213 510S230 720 190 840';const route=state.route==='original'?'M390 -600C440 -410 370 -210 421 -20C396 9 451 15 433 40S372 66 369 99C361 132 354 170 347 246C335 370 405 500 345 840':'M390 -600C440 -410 370 -210 421 -20C396 9 451 15 433 40S372 66 369 99C416 121 427 145 397 170S355 212 347 246C335 370 405 500 345 840';return `<svg class="lakeside-map" viewBox="0 0 660 240" preserveAspectRatio="none" role="img" aria-label="Coastal navigation map with ocean to the left, detailed streets, waterfront parks and Lakeside A5"><defs><linearGradient id="map-base" gradientUnits="userSpaceOnUse" x1="150" y1="-50" x2="570" y2="350"><stop stop-color="#102a43"/><stop offset="1" stop-color="#224558"/></linearGradient><linearGradient id="map-water" gradientUnits="userSpaceOnUse" x1="-300" y1="-200" x2="1000" y2="80"><stop stop-color="#082840"/><stop offset=".65" stop-color="#0a4562"/><stop offset="1" stop-color="#1c6175"/></linearGradient><linearGradient id="park-fill" x2="1" y2="1"><stop stop-color="#386559"/><stop offset="1" stop-color="#244b43"/></linearGradient><filter id="route-glow"><feGaussianBlur stdDeviation="3.5"/></filter><clipPath id="land-clip"><path d="${coast}H1440V-600Z"/></clipPath></defs><g id="map-art" transform="${mapTransform()}"><rect x="-720" y="-600" width="2160" height="1440" fill="url(#map-water)"/><g class="ocean-contours" fill="none" stroke="#63b9ca" stroke-width=".7" stroke-opacity=".12"><path d="M142-600C80-400 185-120 142-20C80 40 185 60 144 117S128 202 158 270S90 540 150 840M109-600C47-400 152-120 109-20C47 40 152 60 111 117S95 202 125 270S57 540 117 840M75-600C13-400 118-120 75-20C13 40 118 60 77 117S61 202 91 270S23 540 83 840M40-600C-22-400 83-120 40-20C-22 40 83 60 42 117S26 202 56 270S-12 540 48 840"/></g><g clip-path="url(#land-clip)"><rect x="-720" y="-600" width="2160" height="1440" fill="url(#map-base)"/><g fill="url(#park-fill)" stroke="#598477" stroke-width=".7" stroke-opacity=".45"><path d="M195 75 245 66 268 96 230 122 204 111Z"/><path d="M256 145 305 124 341 148 314 184 266 186Z"/><path d="M470 13 544 15 526 51 479 57 455 36Z"/><path d="M488 161 536 148 578 180 544 211 490 199Z"/><path d="M212 206 245 197 268 233 255 261 226 265Z"/><path d="M260-205 352-238 414-180 380-132 285-145Z"/><path d="M524-126 648-143 672-69 584-43 518-73Z"/><path d="M292 350 396 329 437 403 352 440 280 410Z"/><path d="M598 422 727 398 765 485 642 530 586 486Z"/><path d="M864 62 984 44 1009 122 903 152 859 113Z"/></g><g fill="none" stroke="#7ba7b6" stroke-opacity=".28" stroke-width=".65">${streets}</g>${blocks}<g fill="none" stroke="#9fb3b7" stroke-opacity=".46" stroke-width="1.6"><path d="M230-20Q285 47 334 77T554 137 720 180M174 158Q331 95 480 93T715 40M282 270Q319 180 464 165T700 217M600-20Q524 52 515 112T425 270"/></g><path d="M232-20Q195 20 205 47T247 102 218 153 264 260" stroke="#91ad92" stroke-opacity=".65" stroke-width="2.2" fill="none"/><path d="M254-20Q220 20 230 47T272 102 243 153 289 260" stroke="#6e987b" stroke-opacity=".35" stroke-width="10" fill="none"/></g><path d="${coast}" fill="none" stroke="#a3bbb4" stroke-width="1.6" stroke-opacity=".7"/><path d="M202-30C179 0 149 22 160 50S214 72 204 105 164 133 175 164 227 202 212 270" fill="none" stroke="#55afc5" stroke-width="4" stroke-opacity=".17"/><g fill="#b4ccce" stroke="none" font-family="Altair,Arial,sans-serif" font-size="7" letter-spacing="1"><text x="68" y="126" fill="#70aabd" transform="rotate(-18 68 126)">PACIFIC OCEAN</text><text x="260" y="161" fill="#94b8a6">COASTAL PARK</text><text x="482" y="35" fill="#94b8a6">NORTH GARDENS</text><text x="452" y="113">RIVERSIDE DR.</text><text x="280" y="66" transform="rotate(-12 280 66)">LAKESIDE A5</text></g><path class="route-aura" d="${route}" fill="none" stroke="#00cbff" stroke-width="12" filter="url(#route-glow)" opacity=".7"/><path id="map-navigation-route" d="${route}" fill="none" stroke="#00cdfa" stroke-width="4.5"/><path class="route-flow" d="${route}" fill="none" stroke="#8ef8ff" stroke-width="1.6" stroke-dasharray="9 28" opacity=".7"/><g class="map-position" transform="translate(362 125)"><ellipse cy="4" rx="24" ry="16" fill="#071e35" opacity=".5"/><ellipse rx="23" ry="17" fill="#3cf0ff" opacity=".2"/><ellipse rx="19" ry="13" fill="#ecfaff"/><path d="m0-10 11 17-11-5-11 5Z" fill="#0879ed"/></g></g></svg>`}

function climate(){return `<div class="climate-strip" aria-label="Climate controls"><div class="temperature driver-temp"><button data-action="cool" aria-label="Decrease driver temperature">−</button><strong>${state.temp.toFixed(1)}°</strong><button data-action="warm" aria-label="Increase driver temperature">+</button></div><div class="climate-functions"><button data-action="seat" aria-label="Seat comfort" aria-pressed="${state.seat}">${icon('Seat')}</button><button data-action="fan" class="${state.fan?'active':''}" aria-label="Cabin fan" aria-pressed="${state.fan}">${icon('Fan')}</button><button data-action="defog" aria-label="Front defog" aria-pressed="${state.defog}">${icon('Defog')}</button><button data-action="rear" aria-label="Rear defog" aria-pressed="${state.rear}">${icon('Rear')}</button></div><div class="temperature passenger-temp"><button data-action="passenger-cool" aria-label="Decrease passenger temperature">−</button><strong>${state.passenger.toFixed(1)}°</strong><button data-action="passenger-warm" aria-label="Increase passenger temperature">+</button></div></div>`}
function navigation(){return `<section class="navigation-display" aria-label="Navigation and climate">${state.app==='Home'?`<div class="map-region" id="map-region" tabindex="0" title="Drag to pan. Use + and − to zoom, 0 to reset.">${cityMap()}<div class="map-status"><span>18:02</span><span class="signal-bars" aria-label="Signal strength"><i></i><i></i><i></i><i></i></span><span>5G</span>${icon('Vehicle')}</div><div class="map-view-controls" role="group" aria-label="Map view"><button data-action="map-out" aria-label="Zoom out map" title="Zoom out">−</button><button data-action="map-in" aria-label="Zoom in map" title="Zoom in">+</button><button data-action="map-reset" aria-label="Recenter map" title="Recenter"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="5"/><path d="M12 2v4m0 12v4M2 12h4m12 0h4"/></svg></button></div><button class="turn-card" data-action="route-detail">${icon('Turn')}<span><strong><span data-journey-distance>${journey().distance}</span> m</strong><small>${state.route==='original'?'Lakeside A5':'Riverside Dr.'}</small></span></button><button class="eta-card" data-action="energy"><strong>ETA <span data-journey-eta>${journey().eta}</span> (<span data-journey-minutes>${journey().minutes}</span> min)</strong><span><span data-journey-remaining>${journey().remaining}</span> km <b>ϟ</b> Supercharger <span>${state.route==='original'?'42':'45'}%</span></span></button><button class="suggestion-card" data-action="suggest-route"><span><strong>+ AI Suggests</strong><small>${state.route==='original'?'Slightly faster via Riverside Dr.':'Riverside Dr. route selected.'}</small></span>${icon('Arrow')}</button></div>`:appPanel()}<div class="map-bottom ${state.app==='Media'?'media-view':''}">${state.app==='Media'?'':music()}${climate()}</div></section>`}
function render(){const focus=document.activeElement;const pageChanged=renderedApp!==state.app;const key=focus?.dataset?.action,app=focus?.dataset?.app,settingsTab=focus?.dataset?.settingsTab,chargeLimit=focus?.dataset?.chargeLimit;$('#cockpit').innerHTML=driver()+`<nav class="icon-rail" aria-label="Applications">${['Home','Media','Phone','Energy','Settings'].map(n=>`<button data-app="${n}" title="${n==='Home'?'Navigation':n==='Media'?'Spotify':n==='Energy'?'Energy & charging':n==='Settings'?'Settings & vehicle':n}" aria-label="${n==='Home'?'Home assistant':n}" ${state.app===n?'aria-current="page"':''}>${icon(n)}</button>`).join('')}</nav>`+navigation();if(!pageChanged)$('.application-screen')?.classList.add('instant');renderedApp=state.app;$('#voice').textContent=state.voice?'Voice on':'Voice off';$('#voice').setAttribute('aria-pressed',state.voice);$('#drive-control').setAttribute('aria-pressed',state.driving);$('#park-control').setAttribute('aria-pressed',!state.driving);if(key)document.querySelector(`[data-action="${key}"]`)?.focus({preventScroll:true});else if(app)document.querySelector(`[data-app="${app}"]`)?.focus({preventScroll:true});else if(settingsTab)document.querySelector(`[data-settings-tab="${settingsTab}"]`)?.focus({preventScroll:true});else if(chargeLimit)document.querySelector(`[data-charge-limit="${chargeLimit}"]`)?.focus({preventScroll:true});syncSpeed();syncMapMarker(false);applyMapView();fit()}
function syncAI(){const el=$('.assistant-home');if(el)el.dataset.state=state.assistant.toLowerCase();const caption=$('#ai-caption');if(caption)caption.textContent=state.reply;$('.voice-wave')?.classList.toggle('active',['Listening','Speaking','Thinking'].includes(state.assistant))}
function act(a){switch(a){case'map-out':zoomMap(-.1);return;case'map-in':zoomMap(.1);return;case'map-reset':state.zoom=1;state.panX=0;state.panY=0;applyMapView();return;case'park':cancelAnimationFrame(driveFrame);state.speed=0;state.driving=false;reply('You’re parked. Take your time.','park');return;case'drive':if(state.driving)return;if(state.door||state.tailgate){toast('Close the driver door and tailgate before driving.');return}state.charge=false;state.app='Home';state.driving=true;state.reply='Drive ready. The lakeside journey continues.';render();accelerate();return;case'play':state.playing=!state.playing;break;case'next':state.track=(state.track+1)%tracks.length;break;case'previous':state.track=(state.track+tracks.length-1)%tracks.length;break;case'cool':state.temp=Math.max(16,state.temp-1);break;case'warm':state.temp=Math.min(28,state.temp+1);break;case'passenger-cool':state.passenger=Math.max(16,state.passenger-1);break;case'passenger-warm':state.passenger=Math.min(28,state.passenger+1);break;case'fan':state.fan=!state.fan;break;case'seat':state.seat=!state.seat;break;case'defog':state.defog=!state.defog;break;case'rear':state.rear=!state.rear;break;case'lane':state.lane=!state.lane;break;case'cruise':state.cruise=!state.cruise;break;case'traffic':state.traffic=!state.traffic;break;case'phone':state.phone=!state.phone;break;case'lock':if(state.door||state.tailgate){toast('Close all doors before locking.');return}if(state.driving){toast('Park before using simulated door controls.');return}state.locked=!state.locked;break;case'like':state.liked=!state.liked;break;case'bluetooth':state.bluetooth=!state.bluetooth;break;case'wifi':state.wifi=!state.wifi;break;case'ambient':state.ambient=!state.ambient;break;case'network':toast('5G connected · MEAVEN hotspot · simulated connection.');return;case'door':case'tailgate':case'windows':if(state.driving){toast('Park before using vehicle opening controls.');return}if(a!=='windows'&&state.locked){toast('Unlock the vehicle before opening.');return}state[a]=!state[a];break;case'charge':if(state.driving){toast('Park before starting the simulated charge.');return}state.charge=!state.charge;if(state.charge){if(state.battery>=state.chargeLimit){state.charge=false;toast('Battery is already at or above the charge limit.');return}state.battery=Math.min(state.chargeLimit,state.battery+5);state.range=Math.round(state.battery*426/82)}break;case'voice':state.voice=!state.voice;if(!state.voice){player?.pause();state.assistant='Ready'}break;case'welcome':state.voice=true;state.app='Home';reply('Try “find a faster route”.','welcome');return;case'talk':talk();return;case'energy':state.app='Energy';break;case'route-detail':{const j=journey();toast(`In ${j.distance} metres, turn right onto ${state.route==='original'?'Lakeside A5':'Riverside Dr.'}. Arrival ${j.eta}, ${j.remaining} kilometres remaining.`);return;}case'suggest-route':state.app='Home';state.assistant='Thinking';render();clearTimeout(thinkTimer);thinkTimer=setTimeout(()=>{state.reply='A faster route via Riverside Dr. Use this route?';state.assistant='Ready';render();showRouteApproval();speak('route')},650);return;case'accept-route':state.route='riverside';$('.route-approval')?.remove();reply('Riverside Dr. selected. Your route is updated.','route-accepted');return;case'keep-route':$('.route-approval')?.remove();state.reply='Keeping your Lakeside A5 route.';state.assistant='Ready';syncAI();return;default:return}render()}
function showRouteApproval(){const e=document.createElement('div');e.className='route-approval';e.setAttribute('role','dialog');e.setAttribute('aria-label','Review route suggestion');e.innerHTML='<strong>Use Riverside Dr.?</strong><span>2 min earlier · 45% arrival battery</span><div><button data-action="keep-route">Keep route</button><button data-action="accept-route">Use route</button></div>';$('.driver-display').append(e);e.querySelector('[data-action="accept-route"]').focus()}
function talk(){if(state.assistant==='Listening'){recognition?.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){state.app='Home';reply('Choose a quick request to explore Lauren.');const e=document.createElement('div');e.className='voice-options';e.innerHTML=`<button class="close-voice" data-voice-close aria-label="Close assistant options">${icon('Close')}</button><strong>How can I help?</strong><button data-request="battery">Battery status</button><button data-request="cabin">Cabin to 22°</button><button data-request="route">Review faster route</button>`;$('.driver-display').append(e);return}if(!confirm('Start microphone input using your browser’s speech service? Audio may be processed by the browser provider.'))return;player?.pause();recognition=new SR();recognition.lang='en-US';recognition.onstart=()=>{state.app='Home';state.assistant='Listening';state.reply='I’m listening.';render()};recognition.onresult=e=>request(e.results[0][0].transcript);recognition.onerror=()=>{state.assistant='Ready';state.reply='Voice input did not start. Try the on-screen controls.';syncAI()};recognition.onend=()=>{if(state.assistant==='Listening'){state.assistant='Ready';syncAI()}};try{recognition.start()}catch{toast('Voice input is unavailable. The on-screen controls remain available.')}}
function request(t){const text=t.toLowerCase();if(/battery|range/.test(text)){state.app='Home';reply(`Battery ${state.battery}%. Estimated range ${state.range} km.`);if([82,87,92,97,100].includes(state.battery))speak('battery-'+state.battery)}else if(/temperature|cabin|degrees/.test(text)){const m=text.match(/\b(1[6-9]|2[0-8])\b/);state.temp=m?+m[0]:22;state.app='Home';reply(`Cabin set to ${state.temp.toFixed(1)}°.`);speak('cabin-'+state.temp,false)}else if(/route|faster|riverside/.test(text))act('suggest-route');else if(/play|music/.test(text)){state.playing=true;state.app='Media';render()}else{state.reply='I can help with cabin comfort, music, battery and your route.';state.assistant='Ready';syncAI()}}
function fit(){const m=$('.screen-mount'),e=$('#cockpit');if(!m||!e)return;const full=document.body.classList.contains('full-size');const width=full?1600:Math.max(innerWidth<=760?900:0,m.parentElement.clientWidth);const scale=width/1600;m.style.width=width+'px';m.style.height=284*scale+'px';e.style.width='1600px';e.style.height='284px';e.style.transform=`scale(${scale})`}
function startupSound(){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const start=audioContext.currentTime;[261.63,392,523.25].forEach((frequency,i)=>{const tone=audioContext.createOscillator(),volume=audioContext.createGain();tone.type='sine';tone.frequency.value=frequency;tone.connect(volume);volume.connect(audioContext.destination);volume.gain.setValueAtTime(0,start+i*.16);volume.gain.linearRampToValueAtTime(.035,start+i*.16+.05);volume.gain.exponentialRampToValueAtTime(.0001,start+i*.16+1.1);tone.start(start+i*.16);tone.stop(start+i*.16+1.2)})}catch{}}
function syncSpeed(){const el=$('.speed strong');if(el)el.textContent=state.speed;$('.speed')?.style.setProperty('--speed-progress',Math.min(1,state.speed/100));$('.driver-display')?.setAttribute('data-speed',state.speed);$('.driver-display')?.style.setProperty('--engine-period',(3-state.speed*.012)+'s')}
function accelerate(){cancelAnimationFrame(driveFrame);const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;const from=state.speed,start=performance.now(),duration=reduced?1200:4200;state.driving=true;if(trafficStartedAt===null){trafficStartedAt=start;$('.road-visual')?.insertAdjacentHTML('beforeend',trafficSequence())}const cruise=[[0,68],[2000,68],[5500,86],[8500,100],[11500,90],[14500,90],[15500,91],[17500,91],[18500,90],[20500,90],[21500,91],[23500,91],[26500,72],[28500,72],[31000,70]];function tick(now){if(!state.driving)return;const elapsed=now-start;let speed;if(elapsed<duration){const p=elapsed/duration;speed=from+(68-from)*(p*p*(3-2*p))}else if(reduced){speed=70}else{const t=elapsed-duration;let k=cruise.findIndex(([time])=>time>t);if(k<0){state.speed=70;syncSpeed();return}const [t0,v0]=cruise[k-1],[t1,v1]=cruise[k];const p=(t-t0)/(t1-t0);speed=v0+(v1-v0)*(p*p*(3-2*p))}state.speed=Math.round(speed);syncSpeed();if(!reduced||elapsed<duration)driveFrame=requestAnimationFrame(tick)}driveFrame=requestAnimationFrame(tick)}

function boot(){clearTimeout(bootTimer);cancelAnimationFrame(bootFrame);cancelAnimationFrame(driveFrame);recognition?.stop();player?.pause();state.speed=0;state.journeyMs=0;state.journeyProgress=0;trafficStartedAt=null;state.driving=false;state.app='Home';state.assistant='Ready';state.reply='Try “find a faster route”.';render();const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;$('#boot').innerHTML='<span class="startup-name">'+$('.review-header .brand-plaque').innerHTML+'</span><div class="logo-loading-line" aria-hidden="true"></div><small>Ready for the road.</small>';$('#boot').classList.remove('boot-enter');void $('#boot').offsetWidth;$('#boot').classList.add('boot-enter');$('#boot').hidden=false;$('#cockpit').classList.add('starting');$('#cockpit').inert=true;startupSound();bootTimer=setTimeout(()=>{$('#boot').hidden=true;$('#cockpit').classList.remove('starting');state.driving=true;render();$('#cockpit').inert=false;$('#cockpit').focus({preventScroll:true});accelerate();speak('welcome')},reduced?350:2400)}

document.addEventListener('click',e=>{const tab=e.target.closest('[data-settings-tab]');if(tab){state.settingsTab=tab.dataset.settingsTab;render();return}const limit=e.target.closest('[data-charge-limit]');if(limit){state.chargeLimit=+limit.dataset.chargeLimit;render();return}const app=e.target.closest('[data-app]');if(app){state.app=app.dataset.app==='Vehicle'?'Settings':app.dataset.app;render();return}const a=e.target.closest('[data-action]');if(a){act(a.dataset.action);return}const t=e.target.closest('[data-track]');if(t){state.track=+t.dataset.track;state.playing=true;render();return}const r=e.target.closest('[data-request]');if(r){$('.voice-options')?.remove();request(r.dataset.request);return}if(e.target.closest('[data-voice-close]'))$('.voice-options')?.remove()});
document.addEventListener('pointerdown',e=>{const region=e.target.closest('.map-region');if(!region||e.target.closest('button'))return;const bounds=region.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,panX:state.panX,panY:state.panY,unitsX:660/bounds.width,unitsY:240/bounds.height};region.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(!drag)return;state.panX=drag.panX+(e.clientX-drag.x)*drag.unitsX;state.panY=drag.panY+(e.clientY-drag.y)*drag.unitsY;applyMapView()});document.addEventListener('pointerup',()=>drag=null);document.addEventListener('pointercancel',()=>drag=null);document.addEventListener('lostpointercapture',()=>drag=null);document.addEventListener('wheel',e=>{if(!e.target.closest('.map-region')||e.target.closest('button'))return;e.preventDefault();zoomMap(e.deltaY<0?.05:-.05)},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.closest?.('#map-region')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','0'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')state.panX=Math.min(mapView.panX,state.panX+18);if(e.key==='ArrowRight')state.panX=Math.max(-mapView.panX,state.panX-18);if(e.key==='ArrowUp')state.panY=Math.min(mapView.panY,state.panY+12);if(e.key==='ArrowDown')state.panY=Math.max(-mapView.panY,state.panY-12);if(e.key==='+')zoomMap(.1);if(e.key==='-')zoomMap(-.1);if(e.key==='0'){state.zoom=1;state.panX=0;state.panY=0}applyMapView();return}if(e.key==='Escape'){recognition?.stop();$('.voice-options')?.remove();$('.route-approval')?.remove()}if(!$('#entry').hidden&&e.key==='Tab'){const items=[...$('#entry').querySelectorAll('button,input')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
setInterval(()=>{if(!state.driving||state.speed===0||state.journeyProgress>=100)return;state.journeyMs+=1000;const progress=Math.min(100,Math.floor(state.journeyMs/5000)*10);if(progress!==state.journeyProgress){state.journeyProgress=progress;syncJourney()}},1000);
$('#enter').onclick=()=>{state.voice=$('#start-voice').checked;$('#entry').hidden=true;$('main').inert=false;$('.review-header').inert=false;render();boot()};$('#restart').onclick=()=>{state.app='Home';render();boot()};$('#voice').onclick=()=>act('voice');$('#welcome').onclick=()=>act('welcome');$('#zoom').onclick=()=>{const full=document.body.classList.toggle('full-size');$('#zoom').textContent=full?'Fit to window':'100% view';$('#zoom').setAttribute('aria-pressed',full);fit()};window.addEventListener('resize',fit);new ResizeObserver(fit).observe($('#screen-scroll'));render();$('main').inert=true;$('.review-header').inert=true;if(!new URLSearchParams(location.search).has('presentation'))$('#enter').focus();
const presentation=new URLSearchParams(location.search);if(presentation.has('presentation')){document.body.classList.add('case-presentation');state.app=['Home','Media','Energy','Settings'].includes(presentation.get('screen'))?presentation.get('screen'):'Home';state.driving=true;state.speed=70;state.journeyProgress=100;state.voice=false;$('#entry').hidden=true;$('main').inert=false;$('.review-header').inert=false;render();$('#cockpit').inert=true;}
})();
